package com.kartyavya.report.controller; import com.kartyavya.report.dto.ReportDtos.*; import com.kartyavya.report.service.ReportService; import jakarta.validation.Valid; import org.springframework.http.MediaType; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/officer") public class OfficerController{private final ReportService s;public OfficerController(ReportService s){this.s=s;}@GetMapping("/reports")List<ReportResponse> reports(Authentication a){return s.officerReports(a);}@GetMapping("/dashboard")Map<String,Object> dashboard(Authentication a){return s.officerDashboard(a);}@PutMapping(value="/reports/{id}/status",consumes=MediaType.MULTIPART_FORM_DATA_VALUE)ReportResponse status(@PathVariable Long id,@Valid @ModelAttribute StatusUpdateRequest r,Authentication a,@RequestHeader(value="X-Correlation-Id",required=false)String c){return s.updateStatus(id,r,a,c);}}
